content.query:
let jobs = union isfuzzy=true (AddonAzureBackupJobs | where TimeGenerated > ago({TimeRange}) | project JobOperation, JobStatus), (datatable(JobOperation:string, JobStatus:string)[]);
let kpiCompleted = jobs | where JobOperation == 'Backup' and JobStatus == 'Completed' | summarize Metric = 'Completed Azure Backup Jobs', Value = toreal(count());
let kpiFailed = jobs | where JobOperation == 'Backup' and JobStatus == 'Failed' | summarize Metric = 'Failed Azure Backup Jobs', Value = toreal(count());
let kpiRestores = jobs | where JobOperation == 'Restore' and JobStatus == 'Completed' | summarize Metric = 'Completed Restore Jobs (Test Evidence)', Value = toreal(count());
let kpiSensitiveOps = AzureActivity | where TimeGenerated > ago({TimeRange}) | where OperationNameValue has_any ('Microsoft.RecoveryServices/vaults/delete', 'Microsoft.RecoveryServices/vaults/backupProtectedItems/delete', 'Microsoft.DataProtection/backupVaults/delete', 'backupconfig/write') | summarize Metric = 'Sensitive Vault / Immutability Changes', Value = toreal(count());
union kpiCompleted, kpiFailed, kpiRestores, kpiSensitiveOps
